#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEAP_CAPACITY 16   /* maximum number of elements the heap can hold */

static long heap[HEAP_CAPACITY];
static int  heap_size = 0;

static void heap_swap(int i, int j)
{
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static void heapify_up(int i)
{
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i])
            break;
        heap_swap(parent, i);
        i = parent;
    }
}

static void heapify_down(int i)
{
    while (1) {
        int left  = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;

        if (left  < heap_size && heap[left]  < heap[smallest])
            smallest = left;
        if (right < heap_size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        heap_swap(i, smallest);
        i = smallest;
    }
}

static int heap_insert(long value)
{
    if (heap_size >= HEAP_CAPACITY)
        return -1;               /* FULL */

    heap[heap_size] = value;
    heapify_up(heap_size);
    heap_size++;
    return 0;
}

static int heap_extract_min(long *out_min)
{
    if (heap_size == 0)
        return -1;               /* EMPTY */

    *out_min = heap[0];
    heap[0] = heap[heap_size - 1];
    heap_size--;
    heapify_down(0);
    return 0;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];

        if (cmd[0] == 'I') {                     /* Insert command */
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            if (endptr == cmd + 1) {             /* no number after 'I' */
                puts("ERR");
                continue;
            }

            if (heap_insert(val) == 0) {
                printf("INS %ld\n", val);
            } else {
                puts("FULL");
            }
        }
        else if (cmd[0] == 'X' && cmd[1] == '\0') {   /* Extract min */
            long min;
            if (heap_extract_min(&min) == 0) {
                printf("MIN %ld\n", min);
            } else {
                puts("EMPTY");
            }
        }
        else {
            puts("ERR");
        }
    }

    return 0;
}
